r=workspace();p=r/'06_reports/vision-feasibility-20261025';b=json.loads((p/'benchmark.json').read_text());s=json.loads((p/'singlepass-benchmark.json').read_text());render=next(x for x in b['rendering'] if x['width']==640);core=next(x for x in b['inference'] if x['backend']=='coreml');cpu=next(x for x in b['inference'] if x['backend']=='cpu4');budget=render['pair_rgbd_p50_ms']+2*core['per_image_p50_ms'];assessment=dict(conclusion='High feasibility for a two-robot RGB-D detection/tracking plus proprioceptive-control prototype on this M4/16GBMac. Full-pose estimation and end-to-end vision-policy training are substantially harder. Real-time30HzdualRGB-D is not demonstrated.',recommended_architecture='RGB/depth cameras -> learned robot detector -> depth-assisted relative localization -> temporal tracking/uncertainty -> opponent-conditioned control; own IMU/encoders/contact estimation for fast stabilization',current_system_is_visual=False,measured_pair_render_ms=render['pair_rgbd_p50_ms'],measured_detector_coreml_ms_per_image=core['per_image_p50_ms'],rough_serial_pair_budget_ms=budget,rough_serial_pair_rate_hz=1000/budget,full_loop_rate_measured=False,recognition_accuracy_measured=False,raw_storage=b['raw_storage_calculation'],singlepass_depth_equivalence_approved=False,source_links=['https://mujoco.readthedocs.io/en/stable/programming/rendering.html','https://mujoco.readthedocs.io/en/stable/APIreference/APIfunctions.html#mjr-readpixels','https://onnxruntime.ai/docs/execution-providers/CoreML-ExecutionProvider.html'],controls=['Keep simulator truth as evaluation/referee information, not actor perception input in visual mode','Keep exact camera images/depth, intrinsics/extrinsics, observation/inference/action timestamps, detections/tracks/confidence/occlusion/failures','Retrain or distill actor onto estimated inputs; do not substitute perfect opponent pose when detection fails','Privileged baseline and visual-sensor experiments must have distinct dataset/version IDs'])
